int run(int argc,wchar_t** argv){check(argc==2,"oracle path");std::ifstream in(std::filesystem::path(argv[1]),std::ios::binary);std::string s{std::istreambuf_iterator<char>(in),{}};auto oracle=JsonObject::Parse(winrt::to_hstring(s));auto rows=oracle.GetNamedArray(L"cases");check(rows.Size()==2268,"oracle coverage");unsigned linked=0;for(unsigned i=0;i<rows.Size();++i){auto row=rows.GetObjectAt(i);context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::run(row);if(i%61==0){RasterHistoryFixture::run(row,true);++linked;}}auto scenes=oracle.GetNamedArray(L"scenes");check(scenes.Size()==45,"scene coverage");for(auto v:scenes){auto row=v.GetObject();context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::scene(row);}auto histories=oracle.GetNamedArray(L"histories");check(histories.Size()==2,"history coverage");for(auto v:histories){auto row=v.GetObject();context=winrt::to_string(row.GetNamedString(L"name"));RasterHistoryFixture::history(row);}context="edges";RasterHistoryFixture::edge(rows.GetObjectAt(0));std::cout<<rows.Size()<<" actual legacy AA results/history, "<<oracle.GetNamedNumber(L"alteredCancels")<<" legacy cancel defects repaired, "<<linked<<" linked variants, 45 command scenes, two palette-change histories, three encoders and task checks passed\n";return 0;}
int wmain(int argc,wchar_t** argv){const auto hr=RoInitialize(RO_INIT_MULTITHREADED);try{const auto result=run(argc,argv);if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return result;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';if(hr==S_OK)winrt::clear_factory_cache();if(SUCCEEDED(hr))RoUninitialize();return 1;}}
